// Общие локаторы списка кандидатов /candidates (для тестов дашборда).
import { Page } from '@playwright/test';

/** Строки таблицы кандидатов. */
export const candidateRows = (page: Page) => page.getByTestId('candidate-row');

/** Ячейка «החלטת גיוס» строки. */
export const decisionCell = (page: Page, row = candidateRows(page)) => row.locator('td[data-label="החלטת גיוס"]');

/** Фильтр статуса (select «סינון לפי סטטוס»). */
export const statusFilter = (page: Page) => page.getByRole('combobox', { name: /^סינון לפי סטטוס/ });

/** Строки с точным именем кандидата. */
export const rowsByName = (page: Page, name: string) =>
  candidateRows(page).filter({ has: page.locator('td[data-label="שם"]').getByText(name, { exact: true }) });

export const EMPTY_RESULT = 'אין מועמדים שמתאימים לחיפוש ולסינון.';
